<?php
declare(strict_types=1);
$config = require __DIR__ . '/../config/database.php';
$pdo = new PDO("mysql:host={$config['host']};dbname={$config['dbname']};charset={$config['charset']}",$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$pdo->exec("UPDATE alumnos SET plan_actual_id=plan_programado_id,plan_programado_id=NULL,plan_programado_desde=NULL,updated_at=NOW() WHERE plan_programado_id IS NOT NULL AND plan_programado_desde IS NOT NULL AND plan_programado_desde<=CURDATE()");
$mesActual=(int)date('n');$anioActual=(int)date('Y');
$sql="SELECT a.id,a.nombre,a.whatsapp,a.correo,a.fecha_inicio,a.estado_administrativo,h.hora_inicio,h.hora_fin,p.nombre plan_nombre,p.sesiones_semana,p.precio,m.estado mensualidad_estado,m.fecha_pago,EXISTS(SELECT 1 FROM curso_intensivo_alumnos cia INNER JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id WHERE cia.alumno_id=a.id AND ci.estado IN ('PROGRAMADO','EN_CURSO')) intensivo_activo FROM alumnos a LEFT JOIN horarios h ON h.id=a.horario_preferido_id LEFT JOIN planes p ON p.id=a.plan_actual_id LEFT JOIN mensualidades m ON m.alumno_id=a.id AND m.mes=:mes AND m.anio=:anio ORDER BY a.nombre";
$stmt=$pdo->prepare($sql);$stmt->execute([':mes'=>$mesActual,':anio'=>$anioActual]);$alumnos=$stmt->fetchAll();
function e(?string $v):string{return htmlspecialchars($v??'',ENT_QUOTES,'UTF-8');}function hora(string $h):string{return date('H:i',strtotime($h));}
function acceso(array $a):array{if($a['estado_administrativo']==='BAJA')return['BAJA','baja'];if($a['estado_administrativo']==='PENDIENTE')return['PENDIENTE DE PAGO','pendiente'];if((int)$a['intensivo_activo']===1)return['INTENSIVO','intensivo'];if(empty($a['plan_nombre']))return['SIN PLAN','pendiente'];if(($a['mensualidad_estado']??'')==='PAGADA')return['PUEDE TOMAR CLASE','acceso'];return['SIN DERECHO A CLASE','sin-acceso'];}
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Control de Alumnos — Hache Natación</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f3f6fa;color:#172033}.contenedor{max-width:1400px;margin:auto;padding:35px 25px}h1{margin:0 0 8px;font-size:32px}.subtitulo,.contador{color:#64748b}.subtitulo{margin-bottom:25px}.contador{margin-bottom:15px;font-size:14px}.tabla-contenedor{background:#fff;border-radius:18px;padding:16px;overflow-x:auto;box-shadow:0 4px 18px rgba(0,0,0,.06)}table{width:100%;border-collapse:collapse;min-width:900px}th{text-align:left;padding:12px;background:#f8fafc;color:#475569;font-size:12px;border-bottom:1px solid #e2e8f0}td{padding:13px 12px;border-bottom:1px solid #edf2f7;vertical-align:middle}.nombre a{font-weight:800;color:#172033;text-decoration:none}.secundario,.precio{color:#64748b;font-size:12px;margin-top:4px}.estado,.derecho{display:inline-block;padding:6px 9px;border-radius:999px;font-size:11px;font-weight:800;white-space:nowrap}.activo,.acceso{background:#dcfce7;color:#166534}.baja,.sin-acceso{background:#fee2e2;color:#991b1b}.pendiente{background:#fef3c7;color:#92400e}.intensivo{background:#dbeafe;color:#1e40af}.plan{font-weight:700}.vacio{text-align:center;padding:50px;color:#64748b}@media(max-width:650px){.contenedor{padding:72px 0 18px}h1,.subtitulo,.contador{margin-left:14px;margin-right:14px}h1{font-size:25px}.subtitulo{font-size:13px;margin-bottom:18px}.tabla-contenedor{border-radius:0;padding:0;box-shadow:none}table{min-width:720px}th{padding:10px 8px}td{padding:11px 8px;font-size:13px}.secundario,.precio{font-size:11px}}</style></head><body><div class="contenedor"><h1>Control de Alumnos</h1><div class="subtitulo">Hache Natación — <?= sprintf('%02d/%d',$mesActual,$anioActual) ?></div><div class="contador"><?= count($alumnos) ?> alumno<?= count($alumnos)===1?'':'s' ?> registrado<?= count($alumnos)===1?'':'s' ?></div><div class="tabla-contenedor"><?php if(!$alumnos):?><div class="vacio">No hay alumnos registrados todavía.</div><?php else:?><table><thead><tr><th>Alumno</th><th>WhatsApp</th><th>Horario</th><th>Plan</th><th>Estado</th><th>Acceso a clase</th></tr></thead><tbody><?php foreach($alumnos as $a):$der=acceso($a);?><tr><td><div class="nombre"><a href="ficha-alumno.php?id=<?=urlencode($a['id'])?>"><?=e($a['nombre'])?></a></div><?php if($a['correo']):?><div class="secundario"><?=e($a['correo'])?></div><?php endif;?></td><td><?=e($a['whatsapp'])?></td><td><?=$a['hora_inicio']&&$a['hora_fin']?hora($a['hora_inicio']).'–'.hora($a['hora_fin']):'—'?></td><td><?php if($a['plan_nombre']):?><div class="plan"><?=e($a['plan_nombre'])?></div><div class="precio"><?=(int)$a['sesiones_semana']?> sesiones · $<?=number_format((float)$a['precio'],0)?></div><?php else:?>—<?php endif;?></td><td><span class="estado <?=$a['estado_administrativo']==='ACTIVO'?'activo':($a['estado_administrativo']==='PENDIENTE'?'pendiente':'baja')?>"><?=e($a['estado_administrativo'])?></span></td><td><span class="derecho <?=$der[1]?>"><?=$der[0]?></span><?php if(in_array($der[0],['SIN DERECHO A CLASE','PENDIENTE DE PAGO'],true)):?><div class="secundario"><a href="pagos.php?alumno_id=<?=urlencode($a['id'])?>&tipo=MENSUALIDAD">Registrar pago</a></div><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></div></body></html>